targets.expr:
floor (
  sum (
    increase (
      sbc_active_sessions_total {
        cluster="$cluster",
        account_name=~"$account_name", 
        account_name!~".*test-call-manager.*"
      }[$__range]
    )
  )
)

sum by (account_name) (
  sbc_active_sessions_gauge {
    cluster="$cluster", 
    container="sbc-inbound", 
    account_name=~"$account_name", 
    account_name!~".*test-call-manager.*"
  }
)

sum by (account_name) (
  sbc_active_sessions_gauge {
    cluster="$cluster",
    container="sbc-outbound", 
    account_name=~"$account_name",
    account_name!~".*test-call-manager.*"
  }
)

sum(
  sum by (account_name) (
    sbc_active_sessions_gauge{
      cluster="$cluster",
      account_name=~"$account_name", 
      account_name!~".*test-call-manager.*"
    }
  )
)

sum(
    container_memory_working_set_bytes{cluster="$cluster", container!="", image!=""}
  * on(namespace,pod)
    group_left(workload, workload_type) namespace_workload_pod:kube_pod_owner:relabel{cluster="$cluster", workload="feature-server", workload_type="statefulset"}
)
